from scipy.optimize import least_squares
def fam(p, which):
    a,b,q,s,c,k,d,r,m,n=p
    x=np.exp(-q*T); y=np.exp(-r*T)
    if which==1:
        f=c*(1-np.exp(-k*eps))*(1+d*y)+m*eps+n*eps**2
    elif which==2:
        f=c*(1-np.exp(-k*eps*(1+d*y)))+m*eps+n*eps**2
    elif which==3:
        f=c*(1-np.exp(-k*np.sqrt(eps)))*(1+d*y)+m*eps+n*eps**2
    elif which==4:
        f=c*(1-np.exp(-k*eps))+m*eps*y+n*eps**2*x+d*eps*np.exp(-k*eps)
    return a+b*x+s*T+f
