import warnings; warnings.filterwarnings('ignore')
from scipy.optimize import least_squares
def run(name, build, npar, trials=40, lo=None, hi=None, seed=0):
    rng=np.random.default_rng(seed); best=(9,None)
    for t in range(trials):
        p0=rng.uniform(lo,hi)
        def fr(p):
            A=build(p)
            c,*_=np.linalg.lstsq(A,sigma,rcond=None); return sigma-A@c
        try:
            r=least_squares(fr,p0,max_nfev=300)
            v=np.mean(r.fun**2)/np.var(sigma)
            if np.isfinite(v) and v<best[0]: best=(v,np.round(r.x,4))
        except Exception as ex: pass
    print(name,best)
